import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E5%86%99%E7%9C%9Fmd%E3%83%A1%E3%83%A2.html","title":"写真mdメモ","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":0.85,"words":255},"filePathRelative":"写真mdメモ.md"}`),a={name:`写真mdメモ.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="写真mdメモ" tabindex="-1"><a class="header-anchor" href="#写真mdメモ"><span>写真mdメモ</span></a></h1><p><a href="./自作アプリ.html">自作アプリ</a></p><ul><li><a href="https://github.com/karino2/PhotoMdMemo" target="_blank" rel="noopener noreferrer">karino2/PhotoMdMemo: Receive photo intent and save and add note md.</a></li></ul><p>日本語名は「写真mdメモ」。<a href="./UFASアーキテクチャ.html">UFASアーキテクチャ</a>で作った、写真とそのメモをプレーンなファイルで保存してリスト表示するアプリ。</p><h2 id="モチベーション" tabindex="-1"><a class="header-anchor" href="#モチベーション"><span>モチベーション</span></a></h2><p>Office Lensがディスコンになってしまい、写真をとってメモをしておく手段が無くなってしまったので、代替が欲しい。 だがもうクラウドサービスとかの都合で乗り換えるのは嫌なので、ローカルに保存するアプリを作る事にした。</p><p>コンセプトとしては、写真を別アプリでとって（vFlat Scanを使っている）、送る、でsyncthingのディレクトリにmdとともに保存していくようなアプリ。</p><p>ちなみにvFlat Scanは画像を複数選んで「共有ー＞画像」で共有する。</p><h2 id="アプリの機能" tabindex="-1"><a class="header-anchor" href="#アプリの機能"><span>アプリの機能</span></a></h2><ul><li>送られてきた写真を「日付-キーワード-通し番号.jpg」で保存する</li><li>同じフォルダに「日付-キーワード.md」ファイルを作り、このファイルにメモと上記jpgへのリンクを書く</li><li>起動時にはこのファイルの一覧を表示する</li></ul><h2 id="とりあえずgeminiに頼んで作ってもらう-2026-03-26-木" tabindex="-1"><a class="header-anchor" href="#とりあえずgeminiに頼んで作ってもらう-2026-03-26-木"><span>とりあえずgeminiに頼んで作ってもらう 2026-03-26 (木)</span></a></h2><p>Android Studioのagent機能がついたのでちょこちょこ頼んで作ってもらう。 とりあえず今使うのは出来た。 vFlat Scanは少し慣れないが、出来上がったデータ自体はこれで良い感じなので、 これでデータを蓄積していって、使いながら直したくなった所だけ直していく感じでやっていこう。</p><p>割と細かく指示するとまぁまぁ思い通りに作ってくれるので、なかなかいいね。 変な依存がないように指示をするとちゃんと変な依存無しで作ってくれる。 単に要求から生成するよりもだいぶ思い通りに動かせるので、メンテナンス出来そうなものが作れるな。</p><p>たまに複雑すぎる事を頼むとタイムアウトしてしまうが、何段階かに分けて指示すれば概ね狙った通りのものが作れるので、これでいいや、という感じ。</p><h2 id="画像をタップして拡大とか出来るようにしてもらう-2026-03-27-金" tabindex="-1"><a class="header-anchor" href="#画像をタップして拡大とか出来るようにしてもらう-2026-03-27-金"><span>画像をタップして拡大とか出来るようにしてもらう 2026-03-27 (金)</span></a></h2><p>ラベルを読むのに画像を拡大したくなったので、画像を別Activityで開いて拡大縮小出来るようにしてもらう。 OneNoteで不満だった拡大出来ない問題が解決して、これまでよりもむしろ良い環境になってしまった。 すばら。</p><h2 id="写真バインダーというアプリも作る。" tabindex="-1"><a class="header-anchor" href="#写真バインダーというアプリも作る。"><span>写真バインダーというアプリも作る。</span></a></h2><p><a href="https://github.com/karino2/PhotoBinder" target="_blank" rel="noopener noreferrer">karino2/PhotoBinder: 写真を台形補正して他のアプリに送るAndroidアプリ</a></p><p>写真をとって台形補正して送るだけのアプリ。なんだかんだで完成までに数時間くらいは掛かるが、簡単につくれるのはいい時代になったものだ。</p>`,19)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};